            parser_advance(p);  /* skip unknown token */
        }
    }

    parser_accept(p, TOK_RPAREN);
    parser_accept(p, TOK_ARROW);

    /* Parse return type */
    FlType *ret_type = fl_type_i64();  /* Default type */
    if (parser_match(p, TOK_IDENT) || parser_match(p, TOK_STAR)) {
        ret_type = parse_type(p);
    }

