#include "../include/parser.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>

/* ===== Lexer ===== */

Lexer *lexer_new(const char *input) {
    Lexer *lex = malloc(sizeof(Lexer));
    lex->input = input;
    lex->pos = 0;
    lex->line = 1;
    lex->col = 1;
    return lex;
}

void lexer_free(Lexer *lex) {
    if (lex) free(lex);
}

static char lexer_peek(Lexer *lex, int offset) {
    return lex->input[lex->pos + offset];
}

static void lexer_advance(Lexer *lex) {
    if (lex->input[lex->pos] == '\n') {
        lex->line++;
        lex->col = 1;
    } else {
        lex->col++;
    }
    lex->pos++;
}

static void lexer_skip_whitespace(Lexer *lex) {
    while (lex->input[lex->pos] && isspace(lex->input[lex->pos])) {
        lexer_advance(lex);
    }
}

static Token lexer_read_number(Lexer *lex) {
    Token tok = { 0 };
    tok.line = lex->line;
    tok.col = lex->col;
    int start = lex->pos;

    while (lex->input[lex->pos] && isdigit(lex->input[lex->pos])) {
        lexer_advance(lex);
    }

    if (lex->input[lex->pos] == '.') {
        tok.kind = TOK_FLOAT;
        lexer_advance(lex);
        while (lex->input[lex->pos] && isdigit(lex->input[lex->pos])) {
            lexer_advance(lex);
        }
        tok.float_value = atof(&lex->input[start]);
    } else {
        tok.kind = TOK_INT;
        tok.int_value = atoll(&lex->input[start]);
    }

    tok.length = lex->pos - start;
    tok.text = &lex->input[start];
    return tok;
}

static Token lexer_read_string(Lexer *lex) {
    Token tok = { 0 };
    tok.line = lex->line;
    tok.col = lex->col;
    tok.kind = TOK_STRING;

    lexer_advance(lex); /* skip opening quote */
    int start = lex->pos;

    while (lex->input[lex->pos] && lex->input[lex->pos] != '"') {
        if (lex->input[lex->pos] == '\\') {
            lexer_advance(lex);
        }
        lexer_advance(lex);
    }

    tok.length = lex->pos - start;
    tok.text = &lex->input[start];

    if (lex->input[lex->pos] == '"') {
        lexer_advance(lex);
    }

    return tok;
}

static Token lexer_read_identifier(Lexer *lex) {
    Token tok = { 0 };
    tok.line = lex->line;
    tok.col = lex->col;
    tok.kind = TOK_IDENT;

    int start = lex->pos;

    while (lex->input[lex->pos] && (isalnum(lex->input[lex->pos]) || lex->input[lex->pos] == '_')) {
        lexer_advance(lex);
    }

    tok.length = lex->pos - start;
    tok.text = &lex->input[start];

    /* Check for keywords */
    if (strncmp(tok.text, "fn", tok.length) == 0 && tok.length == 2) tok.kind = TOK_FN;
    else if (strncmp(tok.text, "return", tok.length) == 0 && tok.length == 6) tok.kind = TOK_RETURN;
    else if (strncmp(tok.text, "if", tok.length) == 0 && tok.length == 2) tok.kind = TOK_IF;
    else if (strncmp(tok.text, "else", tok.length) == 0 && tok.length == 4) tok.kind = TOK_ELSE;
    else if (strncmp(tok.text, "while", tok.length) == 0 && tok.length == 5) tok.kind = TOK_WHILE;
    else if (strncmp(tok.text, "for", tok.length) == 0 && tok.length == 3) tok.kind = TOK_FOR;
    else if (strncmp(tok.text, "in", tok.length) == 0 && tok.length == 2) tok.kind = TOK_IN;
    else if (strncmp(tok.text, "let", tok.length) == 0 && tok.length == 3) tok.kind = TOK_LET;
    else if (strncmp(tok.text, "var", tok.length) == 0 && tok.length == 3) tok.kind = TOK_VAR;
    else if (strncmp(tok.text, "extern", tok.length) == 0 && tok.length == 6) tok.kind = TOK_EXTERN;
    else if (strncmp(tok.text, "struct", tok.length) == 0 && tok.length == 6) tok.kind = TOK_STRUCT;
    else if (strncmp(tok.text, "import", tok.length) == 0 && tok.length == 6) tok.kind = TOK_IMPORT;
    else if (strncmp(tok.text, "match", tok.length) == 0 && tok.length == 5) tok.kind = TOK_MATCH;

    return tok;
}

Token lexer_next(Lexer *lex) {
    lexer_skip_whitespace(lex);

    if (!lex->input[lex->pos]) {
        Token tok = { TOK_EOF, "", 0, 0, 0, lex->line, lex->col };
        return tok;
    }

    char ch = lex->input[lex->pos];

    if (isdigit(ch)) return lexer_read_number(lex);
    if (ch == '"') return lexer_read_string(lex);
    if (isalpha(ch) || ch == '_') return lexer_read_identifier(lex);

    Token tok = { 0 };
    tok.line = lex->line;
    tok.col = lex->col;
    tok.text = &lex->input[lex->pos];
    tok.length = 1;

    if (ch == '+') tok.kind = TOK_PLUS;
    else if (ch == '-') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '>') {
            tok.kind = TOK_ARROW;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_MINUS;
        return tok;
    } else if (ch == '*') tok.kind = TOK_STAR;
    else if (ch == '/') tok.kind = TOK_SLASH;
    else if (ch == '%') tok.kind = TOK_PERCENT;
    else if (ch == '=') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '=') {
            tok.kind = TOK_EQ;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_ASSIGN;
        return tok;
    } else if (ch == '!') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '=') {
            tok.kind = TOK_NE;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_NOT;
        return tok;
    } else if (ch == '<') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '=') {
            tok.kind = TOK_LE;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_LT;
        return tok;
    } else if (ch == '>') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '=') {
            tok.kind = TOK_GE;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_GT;
        return tok;
    } else if (ch == '(') tok.kind = TOK_LPAREN;
    else if (ch == ')') tok.kind = TOK_RPAREN;
    else if (ch == '{') tok.kind = TOK_LBRACE;
    else if (ch == '}') tok.kind = TOK_RBRACE;
    else if (ch == '[') tok.kind = TOK_LBRACKET;
    else if (ch == ']') tok.kind = TOK_RBRACKET;
    else if (ch == ',') tok.kind = TOK_COMMA;
    else if (ch == '.') tok.kind = TOK_DOT;
    else if (ch == ':') tok.kind = TOK_COLON;
    else if (ch == ';') tok.kind = TOK_SEMICOLON;
    else if (ch == '&') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '&') {
            tok.kind = TOK_AND;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_ERROR;
        return tok;
    } else if (ch == '|') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '|') {
            tok.kind = TOK_OR;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_ERROR;
        return tok;
    } else {
        tok.kind = TOK_ERROR;
    }

    lexer_advance(lex);
    return tok;
}

/* ===== Parser ===== */

Parser *parser_new(const char *input) {
    Parser *p = malloc(sizeof(Parser));
    p->lexer = lexer_new(input);
    p->current = lexer_next(p->lexer);
    p->peek = lexer_next(p->lexer);
    return p;
}

void parser_free(Parser *p) {
    if (p) {
        lexer_free(p->lexer);
        free(p);
    }
}

static void parser_advance(Parser *p) {
    p->current = p->peek;
    p->peek = lexer_next(p->lexer);
}

static int parser_match(Parser *p, TokenKind kind) {
    return p->current.kind == kind;
}

static int parser_accept(Parser *p, TokenKind kind) {
    if (parser_match(p, kind)) {
        parser_advance(p);
        return 1;
    }
    return 0;
}

/* Forward declarations */
static FlType *parse_type(Parser *p);
static Expr *parse_primary(Parser *p);
static Expr *parse_postfix(Parser *p, Expr *e);
static Expr *parse_unary(Parser *p);
static Expr *parse_multiplicative(Parser *p);
static Expr *parse_additive(Parser *p);
static Expr *parse_comparison(Parser *p);
static Expr *parse_logical_and(Parser *p);
static Expr *parse_logical_or(Parser *p);
static Expr *parse_assignment(Parser *p);

/* Parse type annotation: i32, f64, string, *i64, etc */
static FlType *parse_type(Parser *p) {
    if (parser_match(p, TOK_STAR)) {
        /* Pointer type: * <type> */
        parser_advance(p);
        FlType *inner = parse_type(p);
        return fl_type_pointer(inner);
    }

    if (parser_match(p, TOK_IDENT)) {
        const char *name = p->current.text;
        int len = p->current.length;
        parser_advance(p);

        /* Check for primitive types */
        if (strncmp(name, "i32", len) == 0)    return fl_type_i32();
        if (strncmp(name, "i64", len) == 0)    return fl_type_i64();
        if (strncmp(name, "f32", len) == 0)    return fl_type_f32();
        if (strncmp(name, "f64", len) == 0)    return fl_type_f64();
        if (strncmp(name, "bool", len) == 0)   return fl_type_bool();
        if (strncmp(name, "void", len) == 0)   return fl_type_void();
        if (strncmp(name, "string", len) == 0) return fl_type_string();

        /* User-defined struct type */
        char sname[256] = {0};
        strncpy(sname, name, len < 255 ? len : 255);
        return fl_type_struct(sname);
    }

    /* Fallback to i64 if we can't parse a type */
    return fl_type_i64();
}

/* Parse struct definition: struct Name { field: type, ... } */
static Stmt *parse_struct(Parser *p) {
    parser_accept(p, TOK_STRUCT);

    /* Parse struct name */
    if (!parser_match(p, TOK_IDENT)) {
        return NULL;  /* Error: expected struct name */
    }
    char struct_name[256] = {0};
    strncpy(struct_name, p->current.text, p->current.length < 255 ? p->current.length : 255);
    parser_advance(p);

    if (!parser_accept(p, TOK_LBRACE)) {
        return NULL;  /* Error: expected { */
    }

    /* Parse struct fields - dynamic array */
    int capacity = 32;
    StructField **fields = malloc(sizeof(StructField *) * capacity);
    int field_count = 0;

    while (!parser_match(p, TOK_RBRACE) && !parser_match(p, TOK_EOF)) {
        /* Grow array if needed */
        if (field_count >= capacity) {
            capacity *= 2;
            StructField **new_fields = malloc(sizeof(StructField *) * capacity);
            for (int i = 0; i < field_count; i++) {
                new_fields[i] = fields[i];
            }
            free(fields);
            fields = new_fields;
        }
        if (!parser_match(p, TOK_IDENT)) {
            parser_advance(p);
            continue;
        }

        /* Parse field name */
        char field_name[256] = {0};
        strncpy(field_name, p->current.text, p->current.length < 255 ? p->current.length : 255);
        parser_advance(p);

        if (!parser_accept(p, TOK_COLON)) {
            continue;  /* Error: expected : */
        }

        /* Parse field type */
        FlType *field_type = parse_type(p);

        fields[field_count] = struct_field_new(field_name, field_type);
        field_count++;

        if (parser_match(p, TOK_COMMA)) {
            parser_advance(p);
        }
    }

    parser_accept(p, TOK_RBRACE);

    return stmt_struct_def(struct_name, fields, field_count);
}

/* Parse primary expression: literal, variable, (expr) */
static Expr *parse_primary(Parser *p) {
    if (parser_match(p, TOK_INT)) {
        Expr *e = expr_literal_int(p->current.int_value);
        parser_advance(p);
        return e;
    } else if (parser_match(p, TOK_FLOAT)) {
        Expr *e = expr_literal_float(p->current.float_value);
        parser_advance(p);
        return e;
    } else if (parser_match(p, TOK_STRING)) {
        /* Copy string without quotes */
        char str[256];
        strncpy(str, p->current.text, p->current.length);
        str[p->current.length] = '\0';
        Expr *e = expr_literal_string(str);
        parser_advance(p);
        return e;
    } else if (parser_match(p, TOK_IDENT)) {
        char ident[256];
        strncpy(ident, p->current.text, p->current.length);
        ident[p->current.length] = '\0';
        parser_advance(p);

        Expr *e = expr_var(ident);
        return parse_postfix(p, e);
    } else if (parser_accept(p, TOK_LPAREN)) {
        Expr *e = parse_expression(p);
        parser_accept(p, TOK_RPAREN);
        return e;
    }

    return expr_literal_int(0); /* error */
}

static Expr *parse_postfix(Parser *p, Expr *e) {
    /* Handle function calls: name(...) */
    if (parser_match(p, TOK_LPAREN)) {
        /* Get function name from expr */
        if (e->kind != EXPR_VAR) {
            return e;  /* not a function call */
        }

        const char *func_name = e->var.name;
        parser_advance(p);  /* skip ( */

        /* Parse arguments - dynamic array */
        int arg_capacity = 32;
        Expr **args = malloc(sizeof(Expr *) * arg_capacity);
        int arg_count = 0;

        while (!parser_match(p, TOK_RPAREN) && !parser_match(p, TOK_EOF)) {
            /* Grow array if needed */
            if (arg_count >= arg_capacity) {
                arg_capacity *= 2;
                Expr **new_args = malloc(sizeof(Expr *) * arg_capacity);
                for (int i = 0; i < arg_count; i++) {
                    new_args[i] = args[i];
                }
                free(args);
                args = new_args;
            }
            args[arg_count++] = parse_expression(p);
            if (parser_match(p, TOK_COMMA)) {
                parser_advance(p);
            }
        }

        parser_accept(p, TOK_RPAREN);

        /* Free the original VAR expr */
        free(e->var.name);
        free(e);

        /* Return CALL expr */
        return expr_call(func_name, args, arg_count);
    }

    /* Handle member access: expr.field */
    if (parser_match(p, TOK_DOT)) {
        parser_advance(p);  /* skip . */
        if (parser_match(p, TOK_IDENT)) {
            char field_name[256] = {0};
            strncpy(field_name, p->current.text, p->current.length < 255 ? p->current.length : 255);
            parser_advance(p);
            e = expr_member(e, field_name);
            /* Recursive postfix (could have more .field accesses) */
            return parse_postfix(p, e);
        }
    }

    /* Handle array indexing: expr[index] */
    if (parser_match(p, TOK_LBRACKET)) {
        parser_advance(p);  /* skip [ */
        Expr *index = parse_expression(p);
        parser_accept(p, TOK_RBRACKET);
        e = expr_index(e, index);
        /* Recursive postfix (could have more [] or .field) */
        return parse_postfix(p, e);
    }

    return e;
}

static Expr *parse_unary(Parser *p) {
    if (parser_accept(p, TOK_NOT)) {
        Expr *operand = parse_unary(p);
        return expr_unary(operand, "!");
    } else if (parser_accept(p, TOK_MINUS)) {
        Expr *operand = parse_unary(p);
        return expr_unary(operand, "-");
    }

    return parse_primary(p);
}

static Expr *parse_multiplicative(Parser *p) {
    Expr *left = parse_unary(p);

    while (parser_match(p, TOK_STAR) || parser_match(p, TOK_SLASH)) {
        const char *op = parser_match(p, TOK_STAR) ? "*" : "/";
        parser_advance(p);
        Expr *right = parse_unary(p);
        left = expr_binary(left, right, op);
    }

    return left;
}

static Expr *parse_additive(Parser *p) {
    Expr *left = parse_multiplicative(p);

    while (parser_match(p, TOK_PLUS) || parser_match(p, TOK_MINUS)) {
        const char *op = parser_match(p, TOK_PLUS) ? "+" : "-";
        parser_advance(p);
        Expr *right = parse_multiplicative(p);
        left = expr_binary(left, right, op);
    }

    return left;
}

static Expr *parse_comparison(Parser *p) {
    Expr *left = parse_additive(p);

    while (parser_match(p, TOK_LT) || parser_match(p, TOK_LE) ||
           parser_match(p, TOK_GT) || parser_match(p, TOK_GE) ||
           parser_match(p, TOK_EQ) || parser_match(p, TOK_NE)) {
        const char *op = "?";
        if (parser_match(p, TOK_LT)) op = "<";
        else if (parser_match(p, TOK_LE)) op = "<=";
        else if (parser_match(p, TOK_GT)) op = ">";
        else if (parser_match(p, TOK_GE)) op = ">=";
        else if (parser_match(p, TOK_EQ)) op = "==";
        else if (parser_match(p, TOK_NE)) op = "!=";

        parser_advance(p);
        Expr *right = parse_additive(p);
        left = expr_binary(left, right, op);
    }

    return left;
}

static Expr *parse_logical_and(Parser *p) {
    Expr *left = parse_comparison(p);

    while (parser_accept(p, TOK_AND)) {
        Expr *right = parse_comparison(p);
        left = expr_binary(left, right, "&&");
    }

    return left;
}

static Expr *parse_logical_or(Parser *p) {
    Expr *left = parse_logical_and(p);

    while (parser_accept(p, TOK_OR)) {
        Expr *right = parse_logical_and(p);
        left = expr_binary(left, right, "||");
    }

    return left;
}

static Expr *parse_assignment(Parser *p) {
    Expr *left = parse_logical_or(p);

    if (parser_accept(p, TOK_ASSIGN)) {
        Expr *right = parse_assignment(p);
        /* For now, create a binary "=" operation (will be code-gen'd as assignment) */
        left = expr_binary(left, right, "=");
    }

    return left;
}

Expr *parse_expression(Parser *p) {
    return parse_assignment(p);
}

Stmt *parse_statement(Parser *p) {
    if (parser_accept(p, TOK_VAR) || parser_accept(p, TOK_LET)) {
        /* Parse variable declaration */
        char name[256];
        strncpy(name, p->current.text, p->current.length);
        name[p->current.length] = '\0';
        parser_advance(p);

        FlType *var_type = fl_type_i64();  /* Default type */
        if (parser_accept(p, TOK_COLON)) {
            /* Parse type annotation (e.g., "i64", "f64", "*i32") */
            var_type = parse_type(p);
        }

        Expr *init = NULL;
        if (parser_accept(p, TOK_ASSIGN)) {
            init = parse_expression(p);
        }

        parser_accept(p, TOK_SEMICOLON);

        return stmt_var_decl(name, var_type, init);
    } else if (parser_accept(p, TOK_MATCH)) {
        /* Parse match expression (simplified: converts to if-else chain) */
        Expr *match_expr = parse_expression(p);
        parser_accept(p, TOK_LBRACE);

        Stmt *result_stmt = NULL;

        while (!parser_match(p, TOK_RBRACE) && !parser_match(p, TOK_EOF)) {
            /* Parse case pattern (simplified: just literals) */
            if (parser_match(p, TOK_INT)) {
                long case_val = p->current.int_value;
                parser_advance(p);

                parser_accept(p, TOK_ARROW);

                /* Create: if (match_expr == case_val) { ... } */
                Expr *case_cond = expr_binary(match_expr, expr_literal_int(case_val), "==");
                Stmt *case_body = parse_statement(p);

                if (result_stmt == NULL) {
                    result_stmt = stmt_if(case_cond, case_body, NULL);
                } else {
                    /* Chain to previous if-else */
                    Stmt *current = result_stmt;
                    while (current->if_stmt.else_body != NULL) {
                        current = current->if_stmt.else_body;
                    }
                    current->if_stmt.else_body = stmt_if(case_cond, case_body, NULL);
                }

                parser_accept(p, TOK_COMMA);
            } else {
                parser_advance(p);
            }
        }

        parser_accept(p, TOK_RBRACE);
        return result_stmt ? result_stmt : stmt_expr(match_expr);

    } else if (parser_accept(p, TOK_IF)) {
        Expr *cond = parse_expression(p);
        Stmt *body = parse_statement(p);
        Stmt *else_body = NULL;

        if (parser_accept(p, TOK_ELSE)) {
            else_body = parse_statement(p);
        }

        return stmt_if(cond, body, else_body);
    } else if (parser_accept(p, TOK_WHILE)) {
        Expr *cond = parse_expression(p);
        Stmt *body = parse_statement(p);
        return stmt_while(cond, body);
    } else if (parser_accept(p, TOK_RETURN)) {
        Expr *val = NULL;
        if (!parser_match(p, TOK_SEMICOLON)) {
            val = parse_expression(p);
        }
        parser_accept(p, TOK_SEMICOLON);
        return stmt_return(val);
    } else if (parser_accept(p, TOK_LBRACE)) {
        /* Block statement - dynamic array */
        int capacity = 32;
        Stmt **stmts = malloc(sizeof(Stmt *) * capacity);
        int count = 0;

        while (!parser_match(p, TOK_RBRACE) && !parser_match(p, TOK_EOF)) {
            /* Grow array if needed */
            if (count >= capacity) {
                capacity *= 2;
                Stmt **new_stmts = malloc(sizeof(Stmt *) * capacity);
                for (int i = 0; i < count; i++) {
                    new_stmts[i] = stmts[i];
                }
                free(stmts);
                stmts = new_stmts;
            }
            stmts[count++] = parse_statement(p);
        }

        parser_accept(p, TOK_RBRACE);

        return stmt_block(stmts, count);
    } else {
        /* Expression statement */
        Expr *e = parse_expression(p);
        parser_accept(p, TOK_SEMICOLON);
        return stmt_expr(e);
    }
}

FuncDef *parse_function(Parser *p) {
    if (!parser_accept(p, TOK_FN)) {
        return NULL;
    }

    char name[256] = {0};
    if (parser_match(p, TOK_IDENT)) {
        strncpy(name, p->current.text, p->current.length < 255 ? p->current.length : 255);
        parser_advance(p);
    }

    parser_accept(p, TOK_LPAREN);

    /* Parse parameters - dynamic arrays */
    int param_capacity = 32;
    char **param_names = malloc(sizeof(char *) * param_capacity);
    FlType **param_types = malloc(sizeof(FlType *) * param_capacity);
    int param_count = 0;

    while (!parser_match(p, TOK_RPAREN) && !parser_match(p, TOK_EOF)) {
        /* Grow arrays if needed */
        if (param_count >= param_capacity) {
            param_capacity *= 2;
            char **new_names = malloc(sizeof(char *) * param_capacity);
            FlType **new_types = malloc(sizeof(FlType *) * param_capacity);
            for (int i = 0; i < param_count; i++) {
                new_names[i] = param_names[i];
                new_types[i] = param_types[i];
            }
            free(param_names);
            free(param_types);
            param_names = new_names;
            param_types = new_types;
        }

        if (parser_match(p, TOK_IDENT)) {
            char pname[256] = {0};
            strncpy(pname, p->current.text, p->current.length < 255 ? p->current.length : 255);
            parser_advance(p);

            FlType *param_type = fl_type_i64();  /* Default type */
            if (parser_accept(p, TOK_COLON)) {
                /* Parse type annotation */
                param_type = parse_type(p);
            }

            param_names[param_count] = strdup(pname);
            param_types[param_count] = param_type;
            param_count++;

            if (parser_match(p, TOK_COMMA)) {
                parser_advance(p);
            }
        } else {
            parser_advance(p);  /* skip unknown token */
        }
    }

    parser_accept(p, TOK_RPAREN);

    /* Support both `fn f() -> Type` and `fn f(): Type` syntax */
    FlType *ret_type = fl_type_i64();  /* Default type */
    if (parser_match(p, TOK_ARROW)) {
        parser_advance(p);  /* consume -> */
        if (parser_match(p, TOK_IDENT) || parser_match(p, TOK_STAR)) {
            ret_type = parse_type(p);
        }
    } else if (parser_match(p, TOK_COLON)) {
        parser_advance(p);  /* consume : */
        if (parser_match(p, TOK_IDENT) || parser_match(p, TOK_STAR)) {
            ret_type = parse_type(p);
        }
    }

    /* Support `fn f(): T = expr` (single-expr body with =) */
    if (parser_match(p, TOK_EQ)) {
        parser_advance(p);  /* consume = */
    }

    /* Parse body or extern declaration */
    Stmt *body = NULL;
    if (parser_match(p, TOK_SEMICOLON)) {
        /* extern fn declaration ends with ; and has no body */
        parser_advance(p);
        body = NULL;
    } else {
        /* regular fn with body */
        body = parse_statement(p);
    }

    return func_def_new(name, (const char **)param_names, param_types, param_count, ret_type, body);
}

/* Load file contents into string */
static char *load_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *buf = malloc(size + 1);
    size_t read = fread(buf, 1, size, f);
    buf[read] = '\0';
    fclose(f);

    return buf;
}

/* Parse an imported module and merge into current program */
static void import_module(const char *path, FuncDef **funcs, int *func_count,
                          Stmt **struct_defs, int *struct_count) {
    char *content = load_file(path);
    if (!content) {
        fprintf(stderr, "Error: Cannot import '%s'\n", path);
        return;
    }

    Parser *imp = parser_new(content);
