    else if (ch == '%') tok.kind = TOK_PERCENT;
    else if (ch == '=') {
        lexer_advance(lex);
        if (lex->input[lex->pos] == '=') {
            tok.kind = TOK_EQ;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_ASSIGN;
        return tok;
