        if (lex->input[lex->pos] == '=') {
            tok.kind = TOK_LE;
            tok.length = 2;
            lexer_advance(lex);
            return tok;
        }
        tok.kind = TOK_LT;
        return tok;
    } else if (ch == '>') {
